  (* [comment removed for export] *)
  Definition Z4F0 (j0 : word) : list cell :=
    [C8 j0; C8 (Z_to_bv 64 DT); C8 (Z_to_bv 64 DST); C8 (Z_to_bv 64 n); C8 (Z_to_bv 64 SS); C8 (Z_to_bv 64 dcap);
     C8 (Z_to_bv 64 (DST + dcap)); C8 (Z_to_bv 64 AZ4_M10); C8 (Z_to_bv 64 AZ4_M7); C8 (Z_to_bv 64 (DST + dcap));
     C8 (Z_to_bv 64 SS); C8 (Z_to_bv 64 (DST + 3 * seg)); C8 (Z_to_bv 64 (DST + 2 * seg)); C8 (Z_to_bv 64 (DST + seg));
     C8 (Z_to_bv 64 (DT + 4))].

  Definition Z4M (mm : amem) (w120 w128 w304 : word) (ws : list word) : Prop :=
    (exists buf, u8arr asegs mm DST (map (Z_to_bv 8) buf) /\ zlen buf = dcap)
    /\ bytes_at asegs mm SS (map (Z_to_bv 8) src)
    /\ bytes_at asegs mm (DT + 4) cbs
    /\ stk asegs mm lo SPF
    /\ (exists j0, rw_cells asegs mm SPF (Z4F0 j0))
    /\ rw_cells asegs mm (SPF + 120) [C8 w120; C8 w128]
    /\ stk asegs mm (SPF + 136) (SPF + 296)
    /\ rw_cells asegs mm (SPF + 296) [C8 (Z_to_bv 64 (DT + 4)); C8 w304]
    /\ stk asegs mm (SPF + 312) (SPF + 320)
    /\ u64arr asegs mm (SPF + 320) ws /\ length ws = 19%nat
    /\ rw_cells asegs mm (SP + -104) FRS
    /\ mem_inv asegs mm /\ munch DW m0 mm /\ wmono asegs m0 mm.

  (* [comment removed for export] *)
  Lemma z4m_stk : forall mm w120 w128 w304 ws, Z4M mm w120 w128 w304 ws -> stk asegs mm lo (SP + -104).
